  "help.faq.cantLogin.a": "올바른 이메일과 비밀번호를 사용하고 있는지 확인하세요. 비밀번호를 잊으셨다면 로그인 화면에서 \"비밀번호를 잊으셨나요?\"를 클릭하세요. 문제가 지속되면 지원 티켓을 생성하세요.",
