  "help.faq.forgotPassword.q": "비밀번호를 잊었습니다",
  "help.faq.forgotPassword.a": "로그인 화면에서 \"비밀번호를 잊으셨나요?\"를 클릭하고 복구 이메일을 통해 비밀번호를 재설정하는 지침을 따르세요.",
  "help.faq.accountSecurity.q": "내 계정이 해킹당한 것 같습니다",
  "help.faq.accountSecurity.a": "즉시 비밀번호를 변경하세요. 보내지 않은 메시지가 있는지 보낸 편지함을 확인하세요. 설정 > 보안에서 2단계 인증을 활성화하세요. 필요시 긴급 티켓을 생성하세요.",
  "help.faq.appAccess.q": "모바일에서 앱에 어떻게 접근하나요?",
  "help.faq.appAccess.a": "chatyy.com.br에서 브라우저를 통해 Chatyy에 접근하거나, 기기 앱 스토어에서 저희 앱을 다운로드하세요.",
  "privacy.title": "개인정보 보호정책",
  "privacy.subtitle": "데이터를 어떻게 보호하고 처리하는지",
  "privacy.lastUpdated": "최종 업데이트: 2026년 3월",
  "privacy.dataCollection.title": "데이터 수집",
  "privacy.dataCollection.body": "이메일 서비스에 필요한 정보만 수집합니다: {name}, 이메일 주소, 발신 및 수신된 메시지 내용. 개인 데이터를 마케팅 목적으로 제3자와 판매하거나 공유하지 않습니다.",
  "privacy.dataUsage.title": "데이터 사용 방법",
  "privacy.dataUsage.body": "귀하의 데이터는 이메일 서비스 운영 및 개선을 위해 사용됩니다. 여기에는 메시지 전달, 스팸 필터링, AI 기능(귀하의 동의 하에) 및 계정 보안이 포함됩니다.",
  "privacy.dataSecurity.title": "데이터 보안",
  "privacy.dataSecurity.body": "모든 전송 및 저장 데이터에 대해 업계 표준 암호화(TLS/SSL)를 사용합니다. 세션은 암호화된 토큰과 CSRF 보호로 보호됩니다. 보안 관행을 정기적으로 감사합니다.",
  "privacy.cookies.title": "쿠키 및 로컬 저장소",
  "privacy.cookies.body": "세션 유지, 선호도(테마, 언어) 기억 및 원활한 경험 제공을 위해 필수 쿠키와 로컬 저장소를 사용합니다. 제3자의 추적 쿠키는 사용하지 않습니다.",
  "privacy.thirdParties.title": "제3자 서비스",
  "privacy.thirdParties.body": "AI(Anthropic Claude) 및 푸시 알림과 같은 특정 기능을 위해 제3자 서비스를 사용할 수 있습니다. 이러한 서비스는 자체 개인정보 보호 정책을 따르며 필요한 최소한의 데이터만 처리합니다.",
  "privacy.rights.title": "귀하의 권리",
  "privacy.rights.body": "언제든지 귀하의 개인 데이터에 접근, 수정, 내보내기 또는 삭제할 권리가 있습니다. 설정에서 데이터를 관리하거나 지원팀에 문의할 수 있습니다.",
  "privacy.contact.title": "문의하기",
  "privacy.contact.body": "개인정보 보호 관련 질문이나 데이터 요청은 privacy@chatyy.com.br로 연락해 주세요. 30일 이내에 답변 드리겠습니다.",
  "terms.title": "서비스 약관",
  "terms.subtitle": "Chatyy 사용 지침",
  "terms.lastUpdated": "최종 업데이트: 2026년 3월",
  "terms.acceptance.title": "약관 수락",
  "terms.acceptance.body": "Chatyy에 접근하거나 사용함으로써 이 서비스 약관에 동의합니다. 약관의 어떤 부분에 동의하지 않으면 서비스를 사용하지 마세요.",
  "terms.services.title": "서비스 설명",
  "terms.services.body": "Chatyy는 이메일을 통한 커뮤니케이션 서비스(이메일 발송, 수신 및 관리)와 AI 기능, 캘린더 통합 및 화상 회의 기능을 제공합니다.",
  "terms.accounts.title": "사용자 계정",
  "terms.accounts.body": "귀하는 귀하의 자격 증명의 보안을 유지할 책임이 있습니다. 비밀번호를 공유하거나 계정에 대한 무단 접근을 허용하지 마세요. 이 서비스를 사용하려면 최소 13세 이상이어야 합니다.",
  "terms.conduct.title": "허용되는 사용",
  "terms.conduct.body": "스팸, 악성 코드, 피싱 또는 불법 콘텐츠를 전송하기 위해 서비스를 사용하지 않기로 동의합니다. 다른 사용자의 계정에 접근하거나 서비스 인프라를 방해하려고 하지 마세요.",
  "terms.content.title": "콘텐츠 소유권",
  "terms.content.body": "귀하는 서비스에서 생성하고 전송하는 모든 콘텐츠에 대한 소유권을 유지합니다. 귀하의 이메일이나 첨부파일에 대한 소유권을 주장하지 않습니다. 서비��를 제공하기 위해 필요한 경우 콘텐츠를 처리할 수 있습니다.",
  "terms.limitation.title": "책임의 한계",
  "terms.limitation.body": "Chatyy는 \"있는 그대로\" 제공됩니다. 99.9%의 가용성을 목표로 하지만 중단 없는 서비스를 보장하지 않습니다. 서비스 사용으로 인한 간접적, 우발적 또는 결과적 손해에 대해서는 책임을 지지 않습니다.",
  "terms.termination.title": "계정 종료",
  "terms.termination.body": "이 약관을 위반하는 계정을 일시 중지하거나 종료할 수 있습니다. 설정에서 언제든지 계정을 삭제할 수 있습니다. 종료 후 30일 이내에 귀하의 데이터가 삭제됩니다.",
  "terms.changes.title": "약관 변경",
  "terms.changes.body": "이 약관은 주기적으로 업데이트될 수 있습니다. 중요한 변경 사항에 대해서는 이메일이나 앱 알림으로 알려드립니다. 변경 후 계속 사용하면 업데이트된 약관에 동의하는 것으로 간주됩니다.",
