  "plans.faqWhatIsPlusAnswer": "Chatyy의 프리미엄 플랜으로 모든 대화, 사진, 비디오를 보호합니다. Chatyy One으로 실수로 삭제한 것도 30일 이내에 복구할 수 있습니다. 또한 200GB의 저장공간과 One AI 개인 비서를 제공하며, 최대 100MB의 파일을 전송할 수 있습니다.",
  "plans.faqCancelAnswer": "당신의 플랜은 유료 기간이 끝날 때까지 활성 상태입니다. 그 이후에는 무료 플랜으로 돌아갑니다. 15GB를 초과하는 사진과 비디오는 다운로드를 위해 30일 동안 유지됩니다.",
  "plans.faqHowFamily": "Pro 플랜은 어떻게 작동하나요?",
  "plans.faqHowFamilyAnswer": "가족 구성원 4명까지 추가할 수 있습니다. 모두 500GB의 저장공간을 공유하며 Chatyy One의 모든 혜택을 누립니다. 각자는 개인 공간을 가지며, 다른 사람의 파일은 볼 수 없습니다.",
  "plans.faqChangePlanAnswer": "네! Plus에서 Pro로 업그레이드하면 비례 차액만 청구됩니다. 다운그레이드 시 현재 플랜은 기간이 끝날 때까지 유지됩니다.",
  "plans.faqCardDeclined": "내 카드가 거부되었습니다. 어떻게 하나요?",
  "plans.faqCardDeclinedAnswer": "카드를 업데이트할 수 있는 기간은 7일입니다. 이 기간 동안 모든 혜택은 계속 작동합니다. 7일 후에는 플랜이 무료로 돌아갑니다.",
  "plans.faqDataSafe": "내 데이터는 안전한가요?",
  "plans.faqDataSafeAnswer": "네! 결제 데이터는 종단 간 암호화로 처리됩니다. 카드 번호는 저장하지 않으며, 마지막 4자리만 참조용으로 저장합니다.",
